/**
 * The instant first view of the waitlist page lives in public/index.html (generated by
 * scripts/brand-sync.ts). The app removes it as soon as the real page is on screen.
 * When the visitor already saw it, the hero skips its entrance animation (the text was
 * already there; animating it again would flicker).
 */
export function removeInstantShell(): void {
  const shell = document.getElementById('ks-shell');
  if (!shell) return;
  if (!shell.hidden) document.documentElement.dataset.shellShown = '1';
  shell.remove();
}

export function shellWasShown(): boolean {
  return document.documentElement.dataset.shellShown === '1';
}
